class SqlHighlighter:public QSyntaxHighlighter {
 QColor keyword,stringColor,comment,number;bool serverDialect=false;
public:
 SqlHighlighter(QTextDocument *doc,bool dark):QSyntaxHighlighter(doc),keyword(dark?"#a9cbff":"#234fa2"),stringColor(dark?"#76dfc1":"#08674e"),comment(dark?"#bac6d6":"#47576c"),number(dark?"#ffca80":"#843f00"){}
 void setServerDialect(bool value){serverDialect=value;rehighlight();}
 void highlightBlock(const QString &s)override{
  int state=qMax(0,previousBlockState());setCurrentBlockState(0);
  static const QSet<QString> words={"CREATE","TABLE","ALTER","ADD","CONSTRAINT","PRIMARY","KEY","FOREIGN","REFERENCES","UNIQUE","CHECK","NOT","NULL","IS","OR","AND","SET","PROPERTY","TRUE","FALSE","ON","DELETE","UPDATE","CASCADE","DEFAULT","GENERATED","BY","AS","IDENTITY","START","WITH","INTEGER","SMALLINT","BIGINT","VARCHAR","CHAR","LONGVARCHAR","DECIMAL","DOUBLE","BOOLEAN","DATE","TIME","TIMESTAMP","CURRENT_DATE","CURRENT_TIME","CURRENT_TIMESTAMP","SELECT","FROM","INSERT","INTO","VALUES","DATABASE","ENGINE","INNODB","AUTO_INCREMENT","DATETIME","LONGTEXT","COLLATE","CHARACTER","SESSION","NAMES","IN","ROW_FORMAT","DYNAMIC","CONVERT","UNHEX","USING"};
  for(int i=0;i<s.size();){int start=i;QChar c=s[i],next=i+1<s.size()?s[i+1]:QChar();
   if(state==4||(c=='/'&&next=='*')){if(state!=4)i+=2;int end=s.indexOf("*/",i);if(end<0){setFormat(start,s.size()-start,comment);state=4;break;}i=end+2;setFormat(start,i-start,comment);state=0;continue;}
   if(state==1||state==2||state==5||c=='\''||c=='"'||c=='`'){if(state==0){state=c=='\''?1:c=='"'?2:5;++i;}QChar quote=state==1?'\'':state==2?'"':'`';bool closed=false;while(i<s.size()){if(s[i++]==quote){if(i<s.size()&&s[i]==quote){++i;continue;}closed=true;break;}}setFormat(start,i-start,stringColor);if(closed)state=0;continue;}
   if((serverDialect&&c=='#')||(c=='-'&&next=='-'&&(!serverDialect||i+2>=s.size()||s[i+2].isSpace()))){setFormat(i,s.size()-i,comment);break;}
   if(c.isLetter()||c=='_'){while(i<s.size()&&(s[i].isLetterOrNumber()||s[i]=='_'))++i;if(words.contains(s.mid(start,i-start).toUpper())){QTextCharFormat fmt;fmt.setForeground(keyword);fmt.setFontWeight(QFont::Bold);setFormat(start,i-start,fmt);}continue;}
   if(c.isDigit()){while(i<s.size()&&(s[i].isDigit()||s[i]=='.'))++i;setFormat(start,i-start,number);continue;}++i;
  }setCurrentBlockState(state);
 }
};
class SqlEditor:public QPlainTextEdit {
 class Gutter:public QWidget{SqlEditor *e;public:explicit Gutter(SqlEditor *owner):QWidget(owner),e(owner){}void paintEvent(QPaintEvent *event)override{e->paintNumbers(event);}};
 Gutter *gutter;
 void updateNumberWidth(){const int width=numberWidth();setViewportMargins(width,0,0,0);gutter->setGeometry(contentsRect().left(),contentsRect().top(),width,contentsRect().height());}
public:
 explicit SqlEditor(QWidget *parent=nullptr):QPlainTextEdit(parent),gutter(new Gutter(this)){
  QFont codeFont("Consolas",11);codeFont.setStyleHint(QFont::Monospace);codeFont.setFixedPitch(true);setFont(codeFont);setLineWrapMode(QPlainTextEdit::NoWrap);setTabStopDistance(fontMetrics().horizontalAdvance(' ')*4);
  gutter->setObjectName("sqlLineNumbers");connect(this,&QPlainTextEdit::blockCountChanged,this,[this]{updateNumberWidth();});
  connect(this,&QPlainTextEdit::updateRequest,this,[this](QRect rect,int dy){if(dy)gutter->scroll(0,dy);else gutter->update(0,rect.y(),gutter->width(),rect.height());if(rect.contains(viewport()->rect()))setViewportMargins(numberWidth(),0,0,0);});setViewportMargins(numberWidth(),0,0,0);
 }
 int numberWidth()const{return 14+fontMetrics().horizontalAdvance('9')*QString::number(qMax(1,blockCount())).size();}
 void resizeEvent(QResizeEvent *e)override{QPlainTextEdit::resizeEvent(e);gutter->setGeometry(contentsRect().left(),contentsRect().top(),numberWidth(),contentsRect().height());}
 void wheelEvent(QWheelEvent *e)override{if(e->modifiers()&Qt::ControlModifier){int size=font().pointSize();if((e->angleDelta().y()>0&&size<26)||(e->angleDelta().y()<0&&size>8))zoomIn(e->angleDelta().y()>0?1:-1);updateNumberWidth();setTabStopDistance(fontMetrics().horizontalAdvance(' ')*4);e->accept();return;}QPlainTextEdit::wheelEvent(e);}
 void paintNumbers(QPaintEvent *e){QPainter p(gutter);p.fillRect(e->rect(),palette().window());p.setPen(palette().color(QPalette::PlaceholderText));auto block=firstVisibleBlock();int index=block.blockNumber();int top=qRound(blockBoundingGeometry(block).translated(contentOffset()).top());while(block.isValid()&&top<=e->rect().bottom()){int height=qRound(blockBoundingRect(block).height());if(block.isVisible()&&top+height>=e->rect().top())p.drawText(0,top,gutter->width()-6,fontMetrics().height(),Qt::AlignRight,QString::number(index+1));top+=height;block=block.next();++index;}}
};

